[
  {
    "title": "technique-row-obscured",
    "claim": "In Image #6, the bottom fade darkens the visible Back Kick row while the preceding technique rows remain clearly readable.",
    "reason": "The presentation obscures information the player is trying to learn.",
    "suggest": "Remove the gradient over the technique text and place a separate 'Scroll for more techniques' cue outside the scrolling list."
  },
  {
    "title": "duplicate-control-headings",
    "claim": "In Image #3, both 'STANCE' and 'TECHNIQUE' appear twice: above the directional instructions and beneath their respective sticks.",
    "reason": "Repeated headings consume space without adding guidance.",
    "suggest": "Consolidate each stick's name and directional instructions into one legend, preserving readable text sizes."
  },
  {
    "title": "player-side-unidentified",
    "claim": "In Image #3, the HUD names Asmongold and HasanAbi but does not visibly identify which fighter the player controls.",
    "reason": "A first-time player must connect the controls to a fighter without an explicit assignment.",
    "suggest": "Add a persistent 'You' label to the player-controlled fighter's nameplate."
  },
  {
    "title": "countdown-without-opt-out",
    "claim": "In Image #18, the result screen displays 'REMATCH' and 'STARTING IN 8' without a visible control to decline that advertised countdown.",
    "reason": "A player who wants to study the result cannot see how to remain on that screen.",
    "suggest": "Add a 'Stay on results' button that cancels the countdown, alongside the existing rematch action."
  },
  {
    "title": "round-clock-meaning-unverified",
    "claim": "Image #18 shows 29s on the HUD and 'FASTEST ROUND 6.4S' in the result summary, but the still cannot establish whether these readouts use the same clock.",
    "reason": "The player cannot tell whether round duration includes introductions, referee calls, or other pauses; this is not evidence that either value is incorrect.",
    "suggest": "Compare timestamped bout boundaries, simulation ticks, and referee pauses, then label the record explicitly as 'Active fight time' or 'Total round time' according to the verified calculation."
  }
]
